   647  static UA_StatusCode
   648  createSecureChannel(void *application, UA_Connection *connection,
   649                      UA_AsymmetricAlgorithmSecurityHeader *asymHeader) {
   650      UA_Server *server = (UA_Server*)application;
   651
   652      /* Iterate over available endpoints and choose the correct one */
   653      UA_Endpoint *endpoint = NULL;
   654      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   655      for(size_t i = 0; i < server->config.endpointsSize; ++i) {
   656          UA_Endpoint *endpointCandidate = &server->config.endpoints[i];
   657          if(!UA_ByteString_equal(&asymHeader->securityPolicyUri,
   658                                  &endpointCandidate->securityPolicy.policyUri))
   659              continue;
   660          retval = endpointCandidate->securityPolicy.asymmetricModule.
   661              compareCertificateThumbprint(&endpointCandidate->securityPolicy,
   662                                           &asymHeader->receiverCertificateThumbprint);
   663          if(retval != UA_STATUSCODE_GOOD)
   664              continue;
   665
   666          /* We found the correct endpoint (except for security mode) The endpoint
   667           * needs to be changed by the client / server to match the security
   668           * mode. The server does this in the securechannel manager */
   669          endpoint = endpointCandidate;
   670          break;
   671      }
   672
   673      if(!endpoint)
   674          return UA_STATUSCODE_BADSECURITYPOLICYREJECTED;
   675
   676      /* Create a new channel */
   677      return UA_SecureChannelManager_create(&server->secureChannelManager, connection,
   678                                            &endpoint->securityPolicy, asymHeader);
   679  }
